-- 出题任务租约：独立增量表，不改写历史任务及题目。
CREATE TABLE IF NOT EXISTS interview_generation_lease (id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '租约记录身份', task_id BIGINT NOT NULL COMMENT '任务逻辑关联身份', attempt_count INT NOT NULL DEFAULT 0 COMMENT '已领取次数', max_attempts INT NOT NULL DEFAULT 3 COMMENT '最大领取次数', lease_owner VARCHAR(80) COMMENT '本次执行令牌', lease_until TIMESTAMP NULL COMMENT '租约截止', next_retry_at TIMESTAMP NULL COMMENT '允许重试时刻', deadline TIMESTAMP NOT NULL COMMENT '任务执行总截止', last_error_code VARCHAR(60) COMMENT '脱敏错误分类', version BIGINT NOT NULL DEFAULT 0 COMMENT '领取版本', create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间', CONSTRAINT uk_igen_lease_task UNIQUE(task_id)) COMMENT='出题任务租约和重试预算，不存储私有正文';
